Future<bool> runAction(BuildContext context,Future<void> Function() action,{String success='Saved successfully'})async{
 try{await action();if(context.mounted){ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(success)));}return true;}
 catch(e){if(context.mounted){ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(friendly(e))));}return false;}
}
